### 3.5 Remotion Lambda Invoker (`lib/remotion/renderer.ts`)

Videos are rendered into an MP4 container at 1080x1920 (9:16 aspect ratio), 30 fps, using AWS Lambda for elastic horizontal scaling.

```typescript
import { renderMediaOnLambda, getRenderProgress } from "@remotion/lambda";

export interface RenderJobProps {
  videoId: string;
  audioUrl: string;
  scenes: any[];
  words: WordAlignment[];
  colorPalette: {
    primary: string;
    accent: string;
    background: string;
  };
}

export async function dispatchRemotionRender(props: RenderJobProps): Promise<{ renderId: string; bucketName: string }> {
  const functionName = process.env.REMOTION_LAMBDA_FUNCTION_NAME!;
  const serveUrl = process.env.REMOTION_SERVE_URL!; // S3 bundle URL
  const region = (process.env.REMOTION_AWS_REGION as any) || "us-east-1";

  const { renderId, bucketName } = await renderMediaOnLambda({
    region,
    functionName,
    serveUrl,
    composition: "MicroLearnVerticalMaster",
    inputProps: props,
    codec: "h264",
    imageFormat: "jpeg",
    maxRetries: 2,
    privacy: "public", // Temporarily public for pipeline download or direct S3 upload
    frameRange: [0, 1799], // 60s @ 30fps = 1800 frames
    timeoutInMilliseconds: 240000,
  });

  return { renderId, bucketName };
}

export async function pollRenderStatus(
  renderId: string, 
  bucketName: string
): Promise<{ done: boolean; outputUrl?: string; error?: string }> {
  const region = (process.env.REMOTION_AWS_REGION as any) || "us-east-1";
  const functionName = process.env.REMOTION_LAMBDA_FUNCTION_NAME!;

  const progress = await getRenderProgress({
    renderId,
    bucketName,
    functionName,
    region,
  });

  if (progress.fatalErrorEncountered) {
    return { done: true, error: progress.errors[0]?.message || "Fatal rendering error" };
  }

  if (progress.done && progress.outputFile) {
    return { done: true, outputUrl: progress.outputFile };
  }

  return { done: false };
}
```

