### 3.8 Daily Batch Ingestion Trigger (`inngest/functions/batch-scheduler.ts`)

This scheduled job queries upcoming delivery windows and initiates generation for topics that do not yet have ready video assets.

```typescript
import { inngest } from "../client";
import { supabaseAdmin } from "@/lib/supabase/service";

export const scheduleDailyVideoGeneration = inngest.createFunction(
  { id: "schedule-daily-video-generation" },
  { cron: "0 2 * * *" }, // Runs daily at 02:00 AM UTC
  async ({ step }) => {
    // 1. Fetch active professions
    const professions = await step.run("fetch-active-professions", async () => {
      const { data, error } = await supabaseAdmin
        .from("niche_professions")
        .select("id, slug")
        .eq("is_active", true);
      if (error) throw error;
      return data;
    });

    // 2. Resolve next topic for each profession & dispatch generation
    for (const profession of professions) {
      await step.run(`queue-profession-${profession.slug}`, async () => {
        // Find next topic that does not have a 'ready' video
        const { data: topic, error: topicErr } = await supabaseAdmin
          .from("topics")
          .select("id, title, category, difficulty_level")
          .eq("profession_id", profession.id)
          .limit(1)
          .single();

        if (topicErr || !topic) return;

        // Create pending entry in generated_videos
        const { data: videoRecord, error: videoErr } = await supabaseAdmin
          .from("generated_videos")
          .insert({
            topic_id: topic.id,
            title: topic.title,
            script: "Pending generation...",
            video_storage_path: "pending",
            thumbnail_storage_path: "pending",
            generation_status: "pending",
          })
          .select("id")
          .single();

        if (videoErr || !videoRecord) return;

        // Send generation event into Inngest queue
        await inngest.send({
          name: "pipeline/video.generate",
          data: {
            videoId: videoRecord.id,
            topicId: topic.id,
            professionSlug: profession.slug,
            topicTitle: topic.title,
            category: topic.category,
            difficultyLevel: topic.difficulty_level,
          },
        });
      });
