## 4. Remotion Dynamic Video Composition (`remotion/Composition.tsx`)

This React composition handles word-by-word active caption highlighting and dynamic scene layout transitions for the 9:16 mobile canvas.

```tsx
import React from "react";
import {
  AbsoluteFill,
  Audio,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

interface Word {
  word: string;
  start: number;
  end: number;
}

interface Scene {
  sequence: number;
  start_second: number;
  end_second: number;
  on_screen_hook: string;
  visual_style: string;
  icon_keyword: string;
}

export const MicroLearnVerticalMaster: React.FC<{
  audioUrl: string;
  scenes: Scene[];
  words: Word[];
  colorPalette: {
    primary: string;
    accent: string;
    background: string;
  };
}> = ({ audioUrl, scenes, words, colorPalette }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const currentTime = frame / fps;

  // Resolve current active scene
  const currentScene = scenes.find(
    (s) => currentTime >= s.start_second && currentTime <= s.end_second
  ) || scenes[0];

  // Resolve active word for kinetic captioning
  const activeWordIndex = words.findIndex(
    (w) => currentTime >= w.start && currentTime <= w.end
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: colorPalette.background,
        color: "#FFFFFF",
        fontFamily: "Inter, sans-serif",
        display: "flex",
        flexDirection: "column",
        justifyContent: "space-between",
        padding: "80px 48px",
      }}
    >
      <Audio src={audioUrl} />

      {/* Top Header: Topic Hook & Progress Bar */}
      <div>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <span
            style={{
              fontSize: 24,
              fontWeight: 800,
              textTransform: "uppercase",
              letterSpacing: 2,
              color: colorPalette.primary,
            }}
          >
            {currentScene.visual_style.replace("_", " ")}
          </span>
          <span style={{ fontSize: 20, color: "#94A3B8" }}>60s MicroLearn</span>
        </div>

        {/* Global Progress Line */}
        <div
          style={{
            marginTop: 16,
            width: "100%",
            height: 6,
            backgroundColor: "rgba(255,255,255,0.1)",
            borderRadius: 3,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              width: `${(currentTime / 60) * 100}%`,
              height: "100%",
              backgroundColor: colorPalette.accent,
            }}
          />
        </div>
      </div>

      {/* Center Dynamic Stage: Visual Cue & Key Hook */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          textAlign: "center",
        }}
      >
        <div
          style={{
            fontSize: 54,
            fontWeight: 900,
            lineHeight: 1.15,
            color: "#FFFFFF",
            maxWidth: 900,
            marginBottom: 24,
          }}
        >
          {currentScene.on_screen_hook}
        </div>
      </div>

      {/* Bottom Kinetic Subtitles (3-word dynamic sliding window) */}
      <div
        style={{
          minHeight: 140,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          backgroundColor: "rgba(0,0,0,0.4)",
          borderRadius: 24,
          padding: "16px 24px",
          backdropFilter: "blur(8px)",
        }}
      >
        <div style={{ fontSize: 42, fontWeight: 700, textAlign: "center" }}>
          {words.map((w, idx) => {
            const isVisible = Math.abs(idx - activeWordIndex) <= 2;
            if (!isVisible) return null;
            const isCurrent = idx === activeWordIndex;

            return (
              <span
                key={idx}
                style={{
                  margin: "0 8px",
                  color: isCurrent ? colorPalette.accent : "#FFFFFF",
                  transform: isCurrent ? "scale(1.1)" : "scale(1)",
                  display: "inline-block",
                  transition: "all 0.1s ease",
                  textDecoration: isCurrent ? "underline" : "none",
                }}
              >
                {w.word}
              </span>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};
```

