### 3.1 Feed Server Component (`app/(app)/feed/page.tsx`)

```tsx
import { redirect } from 'next/navigation';
import { createClient } from '@/lib/supabase/server';
import { FeedContainer } from '@/components/feed/feed-container';
import type { DeliveryWithVideo } from '@/lib/types/feed';

export const dynamic = 'force-dynamic';

export default async function FeedPage() {
  const supabase = await createClient();

  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    redirect('/login');
  }

  // Parallel data fetching: Feed deliveries and User Streaks
  const [deliveriesResponse, streakResponse] = await Promise.all([
    supabase
      .from('user_feed_deliveries')
      .select(`
        id,
        scheduled_for,
        status,
        watched_at,
        watch_duration_seconds,
        is_completed,
        video:generated_videos (
          id,
          title,
          script,
          captions,
          video_storage_path,
          thumbnail_storage_path,
          duration_seconds,
          topic:topics (
            title,
            category,
            difficulty_level
          )
        )
      `)
      .eq('user_id', user.id)
      .order('scheduled_for', { ascending: false })
      .limit(10),
    supabase
      .from('user_streaks')
      .select('current_streak, longest_streak, last_completed_date')
      .eq('user_id', user.id)
      .single(),
  ]);

  if (deliveriesResponse.error) {
    console.error('Error fetching feed:', deliveriesResponse.error);
    throw new Error('Failed to load your learning feed.');
  }

  const rawDeliveries = deliveriesResponse.data || [];

  // Generate short-lived signed URLs for Supabase Storage objects (1 hour TTL)
  const deliveries: DeliveryWithVideo[] = await Promise.all(
    rawDeliveries.map(async (delivery) => {
      const video = Array.isArray(delivery.video) ? delivery.video[0] : delivery.video;

      const [videoSignedUrl, thumbSignedUrl] = await Promise.all([
        supabase.storage
          .from('learning-videos')
          .createSignedUrl(video.video_storage_path, 3600),
        supabase.storage
          .from('learning-thumbnails')
          .createSignedUrl(video.thumbnail_storage_path, 3600),
      ]);

      return {
        ...delivery,
        video: {
          ...video,
          streamUrl: videoSignedUrl.data?.signedUrl || '',
          thumbnailUrl: thumbSignedUrl.data?.signedUrl || '',
        },
      };
    })
  );

  return (
    <main className="relative h-[calc(100dvh-4rem)] w-full max-w-md mx-auto overflow-hidden bg-black md:h-[880px] md:rounded-2xl md:border md:border-neutral-800 md:shadow-2xl">
      <FeedContainer 
        initialDeliveries={deliveries} 
        streak={streakResponse.data}
        userId={user.id}
      />
    </main>
  );
}
```

### 3.2 Feed Client Container (`components/feed/feed-container.tsx`)

```tsx
'use client';

import { useState, useRef, useEffect } from 'react';
import type { DeliveryWithVideo } from '@/lib/types/feed';
import { VideoCard } from '@/components/feed/video-card';
import { Flame } from 'lucide-react';

interface FeedContainerProps {
  initialDeliveries: DeliveryWithVideo[];
  streak: { current_streak: number; longest_streak: number } | null;
  userId: string;
}

export function FeedContainer({ initialDeliveries, streak, userId }: FeedContainerProps) {
  const [deliveries] = useState<DeliveryWithVideo[]>(initialDeliveries);
  const [activeIndex, setActiveIndex] = useState<number>(0);
  const containerRef = useRef<HTMLDivElement>(null);

  // Intersect active video to manage play/pause lifecycle cleanly
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const handleScroll = () => {
      const scrollPosition = container.scrollTop;
      const height = container.clientHeight;
      const newIndex = Math.round(scrollPosition / height);
      if (newIndex !== activeIndex && newIndex >= 0 && newIndex < deliveries.length) {
        setActiveIndex(newIndex);
      }
    };

    container.addEventListener('scroll', handleScroll, { passive: true });
    return () => container.removeEventListener('scroll', handleScroll);
  }, [activeIndex, deliveries.length]);

  return (
    <div className="relative h-full w-full">
      {/* Floating Streak Pill */}
      <header className="absolute top-4 left-4 z-30 flex items-center gap-1.5 rounded-full bg-black/60 px-3 py-1.5 backdrop-blur-md border border-white/10 text-white text-xs font-semibold">
        <Flame className="w-4 h-4 text-orange-500 fill-orange-500 animate-pulse" />
        <span>{streak?.current_streak ?? 0} Day Streak</span>
      </header>

      {/* Vertical Snap Scroll Container */}
      <div
        ref={containerRef}
        className="h-full w-full overflow-y-scroll snap-y snap-mandatory no-scrollbar"
        style={{ scrollBehavior: 'smooth' }}
      >
        {deliveries.map((delivery, index) => (
          <section
            key={delivery.id}
            className="relative h-full w-full snap-start snap-always shrink-0 flex items-center justify-center bg-neutral-950"
          >
            <VideoCard
              delivery={delivery}
              isActive={index === activeIndex}
              isPreloadTarget={Math.abs(index - activeIndex) <= 1}
              userId={userId}
            />
          </section>
        ))}
      </div>
    </div>
  );
}
```

### 3.3 Optimized Video Card Component (`components/feed/video-card.tsx`)

```tsx
