  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    if (isActive) {
      video.play().catch((err) => {
        // Handle autoplay policy block: mute and retry
        console.warn('Autoplay restricted, retrying muted:', err);
        video.muted = true;
        video.play();
      });
    } else {
      video.pause();
    }
  }, [isActive]);

  // Video progress dispatcher (Fires server updates across 5-second intervals and upon completion threshold)
  const handleTimeUpdate = () => {
    const video = videoRef.current;
    if (!video) return;

    const currentSeconds = video.currentTime;
    setDurationWatched(currentSeconds);

    // Completion Threshold: 50 seconds (as defined in DB Schema generated column)
    if (!completed && currentSeconds >= 50.0) {
      setCompleted(true);
      setShowCelebration(true);

      startTransition(async () => {
        await recordWatchProgress({
          deliveryId: delivery.id,
          watchedSeconds: currentSeconds,
          completed: true,
        });
      });
    }
  };

  // Sync state on unmount or slide transition
  useEffect(() => {
    return () => {
      if (videoRef.current && videoRef.current.currentTime > 5) {
        recordWatchProgress({
          deliveryId: delivery.id,
          watchedSeconds: videoRef.current.currentTime,
          completed: videoRef.current.currentTime >= 50.0,
        });
      }
    };
  }, [delivery.id]);

  return (
    <div className="relative h-full w-full overflow-hidden select-none">
      <video
        ref={videoRef}
        src={delivery.video.streamUrl}
        poster={delivery.video.thumbnailUrl}
        preload={isPreloadTarget ? 'auto' : 'none'}
        playsInline
        loop
        className="h-full w-full object-cover"
        onTimeUpdate={handleTimeUpdate}
      />

      {/* Gradient Vignette for UI Readability */}
      <div className="absolute inset-0 bg-gradient-to-b from-black/40 via-transparent to-black/80 pointer-events-none" />

      {/* Completion Effect */}
      {showCelebration && (
        <CompletionCelebration onDismiss={() => setShowCelebration(false)} />
      )}

      {/* Video Metainformation Overlay */}
      <VideoOverlay
        title={delivery.video.title}
        topic={delivery.video.topic}
        script={delivery.video.script}
      />

      {/* Optimistic Interactive Actions (Right Vertical Rail) */}
      <VideoActions
        deliveryId={delivery.id}
        initialCompleted={completed}
        watchDuration={durationWatched}
      />
    </div>
  );
}
