## 4. Server Actions & Optimistic State Architecture

Server Actions in this pattern execute with:
1. Strict session authorization checks using authenticated server clients.
2. Zod-based input validation.
3. Path/Tag revalidation to bust RSC cache layers dynamically.
4. Error boundaries with standardized response schemas.

### 4.1 Feed Server Actions (`lib/actions/feed.ts`)

```typescript
'use server';

import { createClient } from '@/lib/supabase/server';
import { revalidatePath, revalidateTag } from 'next/cache';
import { z } from 'zod';

const ProgressSchema = z.object({
  deliveryId: z.string().uuid(),
  watchedSeconds: z.number().min(0).max(120),
  completed: z.boolean(),
});

export type ActionResponse<T = null> = {
  success: boolean;
  data?: T;
  error?: string;
};

export async function recordWatchProgress(
  input: z.infer<typeof ProgressSchema>
): Promise<ActionResponse> {
  const parseResult = ProgressSchema.safeParse(input);
  if (!parseResult.success) {
    return { success: false, error: 'Invalid progress parameters.' };
  }

  const { deliveryId, watchedSeconds } = parseResult.data;
  const supabase = await createClient();

  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    return { success: false, error: 'Unauthorized.' };
  }

  // Direct UPDATE constrained by RLS (user_id = auth.uid())
  // The PostgreSQL trigger `process_daily_streak_increment` handles streak advancement automatically.
  const { error } = await supabase
    .from('user_feed_deliveries')
    .update({
      watch_duration_seconds: watchedSeconds,
      watched_at: new Date().toISOString(),
    })
    .eq('id', deliveryId)
    .eq('user_id', user.id);

  if (error) {
    console.error('Failed to update watch progress:', error.message);
    return { success: false, error: 'Database synchronization failed.' };
  }

  // Bust cache for the dashboard and streak counters
  revalidateTag(`user-streak-${user.id}`);
  revalidatePath('/dashboard');

  return { success: true };
}

const InteractionSchema = z.object({
  deliveryId: z.string().uuid(),
  bookmarked: z.boolean(),
});

export async function toggleBookmarkAction(
  input: z.infer<typeof InteractionSchema>
): Promise<ActionResponse<{ bookmarked: boolean }>> {
  const { deliveryId, bookmarked } = InteractionSchema.parse(input);
  const supabase = await createClient();

  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) return { success: false, error: 'Unauthorized' };

  // Update JSONB delivery metadata atomically
  const { error } = await supabase
    .from('user_feed_deliveries')
    .update({
      delivery_metadata: { bookmarked },
    })
    .eq('id', deliveryId)
    .eq('user_id', user.id);

  if (error) {
    return { success: false, error: error.message };
  }

  revalidatePath('/archive');
  return { success: true, data: { bookmarked } };
}
```

