## 2. Interactive Player Component Logic

### 2.1 Complete Video Scroller (`components/feed/feed-scroller.tsx`)
This orchestrates the sliding window, handles touch velocity and keyboard navigation, and provides unified audio management.

```tsx
'use client';

import React, { useState, useEffect, useRef, useCallback } from 'react';
import type { DeliveryWithVideo } from '@/lib/types/feed';
import { VideoPlayerItem } from '@/components/feed/video-player-item';
import { Volume2, VolumeX, Flame } from 'lucide-react';

interface FeedScrollerProps {
  deliveries: DeliveryWithVideo[];
  streak: { current_streak: number; longest_streak: number } | null;
  userId: string;
}

export function FeedScroller({ deliveries, streak, userId }: FeedScrollerProps) {
  const [activeIndex, setActiveIndex] = useState<number>(0);
  const [isGlobalMuted, setIsGlobalMuted] = useState<boolean>(true);
  const containerRef = useRef<HTMLDivElement>(null);

  // Restore audio preference from session storage
  useEffect(() => {
    const savedAudioState = sessionStorage.getItem('microlearn_audio_unlocked');
    if (savedAudioState === 'true') {
      setIsGlobalMuted(false);
    }
  }, []);

  const toggleGlobalMute = useCallback(() => {
    setIsGlobalMuted((prev) => {
      const next = !prev;
      sessionStorage.setItem('microlearn_audio_unlocked', String(!next));
      return next;
    });
  }, []);

  // Keyboard navigation handler (Desktop / Tablet with keyboard)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (['ArrowDown', 'j', 'J'].includes(e.key)) {
        e.preventDefault();
        scrollToIndex(activeIndex + 1);
      } else if (['ArrowUp', 'k', 'K'].includes(e.key)) {
        e.preventDefault();
        scrollToIndex(activeIndex - 1);
      } else if (['m', 'M'].includes(e.key)) {
        e.preventDefault();
        toggleGlobalMute();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [activeIndex, toggleGlobalMute]);

  const scrollToIndex = (index: number) => {
    if (index < 0 || index >= deliveries.length || !containerRef.current) return;
    const targetY = index * containerRef.current.clientHeight;
    containerRef.current.scrollTo({
      top: targetY,
      behavior: 'smooth',
    });
  };

  // Viewport intersection observer to track active index
  const handleScroll = useCallback(() => {
    const container = containerRef.current;
    if (!container) return;
    const height = container.clientHeight;
    if (height === 0) return;

    const currentScroll = container.scrollTop;
    const computedIndex = Math.round(currentScroll / height);

    if (computedIndex !== activeIndex && computedIndex >= 0 && computedIndex < deliveries.length) {
      setActiveIndex(computedIndex);
    }
  }, [activeIndex, deliveries.length]);

  return (
    <div className="relative w-full h-[100dvh] bg-black overflow-hidden select-none">
      {/* HUD Header: Persistent Streak & Global Audio Toggle */}
      <header className="absolute top-4 inset-x-4 z-40 flex items-center justify-between pointer-events-none">
        <div className="pointer-events-auto flex items-center gap-2 rounded-full bg-black/60 px-3.5 py-1.5 backdrop-blur-md border border-white/10 shadow-lg">
          <Flame className="w-4 h-4 text-amber-500 fill-amber-500 animate-pulse" />
          <span className="text-white text-xs font-semibold tracking-wide">
            {streak?.current_streak ?? 0} Day Streak
          </span>
        </div>

        <button
          onClick={toggleGlobalMute}
          className="pointer-events-auto flex h-10 w-10 items-center justify-center rounded-full bg-black/60 backdrop-blur-md border border-white/10 text-white shadow-lg active:scale-95 transition-transform"
          aria-label={isGlobalMuted ? 'Unmute feed' : 'Mute feed'}
        >
          {isGlobalMuted ? (
            <VolumeX className="w-5 h-5 text-neutral-300" />
          ) : (
            <Volume2 className="w-5 h-5 text-emerald-400" />
          )}
        </button>
      </header>

      {/* Snap Scroll Viewport */}
      <main
        ref={containerRef}
        onScroll={handleScroll}
        className="w-full h-full overflow-y-scroll snap-y snap-mandatory no-scrollbar"
        style={{ scrollBehavior: 'smooth', WebkitOverflowScrolling: 'touch' }}
      >
        {deliveries.map((delivery, index) => {
          // Fixed 3-node sliding window: only render real video players within distance <= 1
          const shouldMountVideo = Math.abs(index - activeIndex) <= 1;

          return (
            <section
              key={delivery.id}
              className="relative w-full h-[100dvh] snap-start snap-always shrink-0 overflow-hidden bg-neutral-950 flex items-center justify-center"
            >
              <VideoPlayerItem
                delivery={delivery}
                isActive={index === activeIndex}
                shouldMountVideo={shouldMountVideo}
                isGlobalMuted={isGlobalMuted}
                onToggleMute={toggleGlobalMute}
                userId={userId}
              />
            </section>
          );
        })}
      </main>
    </div>
  );
}
```

### 2.2 Low-Latency HLS & Gesture Engine (`components/feed/video-player-item.tsx`)
This component encapsulates Hls.js initialization, native HLS fallback, tap-to-pause, double-tap-to-heart, live subtitles synced from word-level JSON timestamps, and a 60-second progress bar.

```tsx
'use client';

import React, { useRef, useEffect, useState, useCallback } from 'react';
import Image from 'next/image';
import Hls from 'hls.js';
import type { DeliveryWithVideo } from '@/lib/types/feed';
import { recordWatchProgress } from '@/lib/actions/feed';
import { Heart, Bookmark, Share2, Play, Check } from 'lucide-react';
import { HabitCelebrationModal } from './habit-celebration-modal';

interface WordCaption {
  word: string;
  start: number; // in seconds
  end: number;
}

interface VideoPlayerItemProps {
  delivery: DeliveryWithVideo;
  isActive: boolean;
  shouldMountVideo: boolean;
  isGlobalMuted: boolean;
  onToggleMute: () => void;
  userId: string;
}

export function VideoPlayerItem({
  delivery,
  isActive,
  shouldMountVideo,
  isGlobalMuted,
  onToggleMute,
}: VideoPlayerItemProps) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const hlsRef = useRef<Hls | null>(null);

  // Playback States
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [currentTime, setCurrentTime] = useState<number>(0);
  const [duration, setDuration] = useState<number>(60);
  const [isCompleted, setIsCompleted] = useState<boolean>(delivery.is_completed);
  const [showCelebration, setShowCelebration] = useState<boolean>(false);
  const [currentWord, setCurrentWord] = useState<string>('');
  const [showHeartAnim, setShowHeartAnim] = useState<boolean>(false);
  const [isBookmarked, setIsBookmarked] = useState<boolean>(false);

  // Gesture Tracker
  const lastTapRef = useRef<number>(0);
  const singleTapTimerRef = useRef<NodeJS.Timeout | null>(null);

  const captions: WordCaption[] = React.useMemo(() => {
    if (!delivery.video.captions) return [];
    return (delivery.video.captions as unknown as { words: WordCaption[] }).words || [];
  }, [delivery.video.captions]);

  // Clean Hls Instance
  const destroyHls = useCallback(() => {
    if (hlsRef.current) {
      hlsRef.current.destroy();
      hlsRef.current = null;
    }
  }, []);

  // Initialize Adaptive Player (HLS.js or Native HLS)
  useEffect(() => {
    if (!shouldMountVideo) {
      destroyHls();
      return;
    }

    const videoEl = videoRef.current;
    if (!videoEl) return;

    const streamUrl = delivery.video.streamUrl;

    if (videoEl.canPlayType('application/vnd.apple.mpegurl')) {
      // Native Safari HLS
      videoEl.src = streamUrl;
    } else if (Hls.isSupported()) {
      // Media Source Extensions for Chrome / Edge / Firefox / Android
      const hls = new Hls({
        enableWorker: true,
        lowLatencyMode: true,
        backBufferLength: 10,
        maxBufferLength: 20, // 20s max buffer to conserve memory
        maxMaxBufferLength: 30,
        startLevel: -1, // Auto ABR resolution selector
      });

      hls.loadSource(streamUrl);
      hls.attachMedia(videoEl);
      hlsRef.current = hls;

      hls.on(Hls.Events.ERROR, (_, data) => {
        if (data.fatal) {
          switch (data.type) {
            case Hls.ErrorTypes.NETWORK_ERROR:
              hls.startLoad();
              break;
            case Hls.ErrorTypes.MEDIA_ERROR:
              hls.recoverMediaError();
              break;
            default:
              destroyHls();
              break;
          }
        }
      });
    } else {
      // Direct MP4 Fallback
      videoEl.src = streamUrl;
    }

    return () => {
      destroyHls();
    };
  }, [shouldMountVideo, delivery.video.streamUrl, destroyHls]);

  // Sync Global Mute with local element
  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.muted = isGlobalMuted;
    }
  }, [isGlobalMuted]);

  // Play / Pause orchestration based on Viewport State
  useEffect(() => {
    const video = videoRef.current;
    if (!video || !shouldMountVideo) return;

    if (isActive) {
      const playPromise = video.play();
      if (playPromise !== undefined) {
        playPromise
          .then(() => setIsPlaying(true))
          .catch((err) => {
            console.warn('Autoplay prevented, fallback to muted:', err);
            video.muted = true;
            video.play().then(() => setIsPlaying(true));
          });
      }
    } else {
      video.pause();
      setIsPlaying(false);
    }
  }, [isActive, shouldMountVideo]);

  // High-Resolution Time Tracking & Caption Alignment
  const handleTimeUpdate = () => {
    const video = videoRef.current;
    if (!video) return;

    const currentSec = video.currentTime;
    setCurrentTime(currentSec);

    // Dynamic word caption selection
    if (captions.length > 0) {
      const match = captions.find(
        (c) => currentSec >= c.start && currentSec <= c.end
      );
      setCurrentWord(match ? match.word : '');
    }

    // Completion Milestone Trigger (50s threshold as specified in DB Schema)
    if (!isCompleted && currentSec >= 50.0) {
      setIsCompleted(true);
      setShowCelebration(true);

      recordWatchProgress({
        deliveryId: delivery.id,
        watchedSeconds: currentSec,
        completed: true,
      });
    }
  };

  const handleLoadedMetadata = () => {
    if (videoRef.current) {
      setDuration(videoRef.current.duration || 60);
    }
  };

  // Touch Gesture Engine: Disambiguate Single-Tap (Play/Pause) vs Double-Tap (Heart)
  const handleScreenTouch = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    const now = Date.now();
    const DOUBLE_TAP_THRESHOLD = 280; // ms

    if (now - lastTapRef.current < DOUBLE_TAP_THRESHOLD) {
      // Double tap detected
      if (singleTapTimerRef.current) {
        clearTimeout(singleTapTimerRef.current);
        singleTapTimerRef.current = null;
      }
      triggerHeartAnimation();
      lastTapRef.current = 0;
    } else {
      lastTapRef.current = now;
      singleTapTimerRef.current = setTimeout(() => {
        togglePlayPause();
        singleTapTimerRef.current = null;
      }, DOUBLE_TAP_THRESHOLD);
    }
  };

  const togglePlayPause = () => {
    const video = videoRef.current;
    if (!video) return;

    if (video.paused) {
      video.play();
      setIsPlaying(true);
    } else {
      video.pause();
      setIsPlaying(false);
    }
  };

