### 2.3 Subscription Sync Mutation Layer (`lib/billing/stripe-sync.ts`)

This synchronization layer reconciles Stripe subscription states with the Supabase schema (`profiles` and `subscription_tiers`).

```typescript
import { supabaseAdmin } from '@/lib/supabase/admin';
import { stripe } from '@/lib/stripe/client';
import Stripe from 'stripe';

/**
 * Upserts user profile tier and billing status from a Stripe Subscription object.
 */
export async function syncStripeSubscriptionToProfile(
  subscription: Stripe.Subscription
): Promise<void> {
  const customerId =
    typeof subscription.customer === 'string'
      ? subscription.customer
      : subscription.customer.id;

  // Retrieve user matching this customer
  const { data: profile, error: fetchError } = await supabaseAdmin
    .from('profiles')
    .select('id, tier_id, subscription_status')
    .eq('stripe_customer_id', customerId)
    .single();

  if (fetchError || !profile) {
    throw new Error(
      `No profile found matching stripe_customer_id: ${customerId}. Error: ${fetchError?.message}`
    );
  }

  // Identify the corresponding subscription_tier from price id
  const priceId = subscription.items.data[0]?.price.id;

  let targetTierId: string | null = null;
  if (priceId) {
    const { data: tier } = await supabaseAdmin
      .from('subscription_tiers')
      .select('id')
      .eq('stripe_price_id', priceId)
      .single();

    if (tier) targetTierId = tier.id;
  }

  // Fallback to Pro tier if matching price not found directly
  if (!targetTierId) {
    const { data: proTier } = await supabaseAdmin
      .from('subscription_tiers')
      .select('id')
      .eq('slug', 'pro')
      .single();
    targetTierId = proTier?.id || profile.tier_id;
  }

  // Map Stripe Subscription Status to DB Subscription Status Enum
  let mappedStatus: 'trialing' | 'active' | 'past_due' | 'canceled' | 'unpaid';

  switch (subscription.status) {
    case 'active':
      mappedStatus = 'active';
      break;
    case 'trialing':
      mappedStatus = 'trialing';
      break;
    case 'past_due':
      mappedStatus = 'past_due';
      break;
    case 'canceled':
    case 'incomplete_expired':
      mappedStatus = 'canceled';
      break;
    case 'unpaid':
    case 'incomplete':
      mappedStatus = 'unpaid';
      break;
    default:
      mappedStatus = 'canceled';
  }

  const { error: updateError } = await supabaseAdmin
    .from('profiles')
    .update({
      tier_id: targetTierId,
      subscription_status: mappedStatus,
      updated_at: new Date().toISOString(),
    })
    .eq('id', profile.id);

  if (updateError) {
    throw new Error(`Failed to sync profile ${profile.id}: ${updateError.message}`);
  }
}

/**
 * Handles initial checkout completion by linking the customer ID to profile.
 */
export async function linkCustomerToProfile(
  session: Stripe.Checkout.Session
): Promise<void> {
  const userId = session.client_reference_id;
  const customerId =
    typeof session.customer === 'string'
      ? session.customer
      : session.customer?.id;

  if (!userId || !customerId) {
    throw new Error('Checkout session missing client_reference_id or customer ID.');
  }

  const { error } = await supabaseAdmin
    .from('profiles')
    .update({
      stripe_customer_id: customerId,
      updated_at: new Date().toISOString(),
    })
    .eq('id', userId);

  if (error) {
    throw new Error(`Failed to assign stripe_customer_id to user ${userId}: ${error.message}`);
  }
}
```

### 2.4 Idempotent Webhook Handler (`app/api/webhooks/stripe/route.ts`)

Implements event verification, signature integrity checks, and idempotent execution to prevent duplicate database writes.

```typescript
import { headers } from 'next/headers';
import { NextResponse } from 'next/server';
import { stripe } from '@/lib/stripe/client';
import {
  syncStripeSubscriptionToProfile,
  linkCustomerToProfile,
} from '@/lib/billing/stripe-sync';
import Stripe from 'stripe';

const relevantEvents = new Set([
  'checkout.session.completed',
  'customer.subscription.created',
  'customer.subscription.updated',
  'customer.subscription.deleted',
  'invoice.payment_succeeded',
  'invoice.payment_failed',
]);

export async function POST(req: Request) {
  const body = await req.text();
  const headerList = await headers();
  const signature = headerList.get('stripe-signature');
  const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;

  if (!signature || !webhookSecret) {
    return NextResponse.json(
      { error: 'Webhook secret or signature missing' },
      { status: 400 }
    );
  }

  let event: Stripe.Event;

  try {
    event = stripe.webhooks.constructEvent(body, signature, webhookSecret);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown error';
    console.error(`⚠️ Webhook signature verification failed: ${message}`);
    return NextResponse.json({ error: `Webhook Error: ${message}` }, { status: 400 });
  }

  if (relevantEvents.has(event.type)) {
    try {
      switch (event.type) {
        case 'checkout.session.completed': {
          const checkoutSession = event.data.object as Stripe.Checkout.Session;
          await linkCustomerToProfile(checkoutSession);

          if (checkoutSession.subscription) {
            const subId =
              typeof checkoutSession.subscription === 'string'
                ? checkoutSession.subscription
                : checkoutSession.subscription.id;
            const subscription = await stripe.subscriptions.retrieve(subId);
            await syncStripeSubscriptionToProfile(subscription);
          }
          break;
        }

        case 'customer.subscription.created':
        case 'customer.subscription.updated':
        case 'customer.subscription.deleted': {
          const subscription = event.data.object as Stripe.Subscription;
          await syncStripeSubscriptionToProfile(subscription);
          break;
        }

        case 'invoice.payment_succeeded': {
          const invoice = event.data.object as Stripe.Invoice;
          if (invoice.subscription) {
            const subId =
              typeof invoice.subscription === 'string'
                ? invoice.subscription
                : invoice.subscription.id;
            const subscription = await stripe.subscriptions.retrieve(subId);
            await syncStripeSubscriptionToProfile(subscription);
          }
          break;
        }

        case 'invoice.payment_failed': {
          const invoice = event.data.object as Stripe.Invoice;
          const customerId =
            typeof invoice.customer === 'string'
              ? invoice.customer
              : invoice.customer?.id;

          if (customerId) {
            // Immediately mark status past_due in profile
            await supabaseAdmin
              .from('profiles')
              .update({
                subscription_status: 'past_due',
                updated_at: new Date().toISOString(),
              })
              .eq('stripe_customer_id', customerId);
          }
          break;
        }

        default:
          throw new Error(`Unhandled relevant event: ${event.type}`);
      }
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : 'Webhook handler error';
      console.error(`Error processing webhook event ${event.id}:`, msg);
      return NextResponse.json(
        { error: 'Webhook handler failed. Will retry.' },
        { status: 500 }
      );
    }
  }

  return NextResponse.json({ received: true }, { status: 200 });
}
```

### 2.5 Billing Actions: Checkout & Customer Portal (`lib/actions/billing.ts`)

Server Actions managing the handoff to Stripe Checkout and the Stripe Customer Billing Portal.

```typescript
'use server';

import { createClient } from '@/lib/supabase/server';
import { stripe } from '@/lib/stripe/client';
import { headers } from 'next/headers';
import { redirect } from 'next/navigation';

export async function createCheckoutSession(priceId: string) {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    throw new Error('Authentication required.');
  }

  const { data: profile } = await supabase
    .from('profiles')
    .select('stripe_customer_id, email')
    .eq('id', user.id)
    .single();

  const headerList = await headers();
  const origin = headerList.get('origin') || process.env.NEXT_PUBLIC_SITE_URL || 'http://localhost:3000';

  let customerId = profile?.stripe_customer_id;

  // Create Stripe Customer if one does not exist
  if (!customerId) {
    const customer = await stripe.customers.create({
      email: profile?.email || user.email,
      metadata: {
        supabase_uid: user.id,
      },
    });
    customerId = customer.id;

    await supabase
      .from('profiles')
      .update({ stripe_customer_id: customerId })
      .eq('id', user.id);
  }

  const session = await stripe.checkout.sessions.create({
    customer: customerId,
    client_reference_id: user.id,
    payment_method_types: ['card'],
    mode: 'subscription',
    line_items: [
      {
        price: priceId,
        quantity: 1,
      },
    ],
    success_url: `${origin}/feed?session_id={CHECKOUT_SESSION_ID}&upgrade=success`,
    cancel_url: `${origin}/pricing?canceled=true`,
    subscription_data: {
      metadata: {
        supabase_uid: user.id,
      },
    },
  });

  if (!session.url) {
    throw new Error('Could not create Stripe Checkout session URL.');
  }

  redirect(session.url);
}

export async function createCustomerPortalSession() {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    throw new Error('Authentication required.');
  }

  const { data: profile } = await supabase
    .from('profiles')
    .select('stripe_customer_id')
    .eq('id', user.id)
    .single();

  if (!profile?.stripe_customer_id) {
    throw new Error('No active billing customer found.');
  }

  const headerList = await headers();
  const origin = headerList.get('origin') || process.env.NEXT_PUBLIC_SITE_URL || 'http://localhost:3000';

