## 3. Tier Entitlements & Guard Service

### 3.1 Entitlement Guard (`lib/billing/entitlements.ts`)

Calculates user access rights by verifying active subscriptions, delinquent statuses, and the 3-day trial exhaustion rule.

```typescript
import { createClient } from '@/lib/supabase/server';

export interface UserEntitlements {
  canAccessDailyFeed: boolean;
  canChangeProfession: boolean;
  isPro: boolean;
  isTrialing: boolean;
  isTrialExpired: boolean;
  streakDaysCompleted: number;
  reason?: 'TRIAL_EXPIRED' | 'PAST_DUE' | 'CANCELED' | 'ACTIVE';
}

export async function checkUserEntitlements(userId: string): Promise<UserEntitlements> {
  const supabase = await createClient();

  // Query Profile with joined Tier and Streaks
  const { data: profile } = await supabase
    .from('profiles')
    .select(`
      subscription_status,
      tier:subscription_tiers (
        slug,
        daily_video_limit,
        max_professions
      ),
      streaks:user_streaks (
        current_streak,
        longest_streak
      )
    `)
    .eq('id', userId)
    .single();

  if (!profile) {
    return {
      canAccessDailyFeed: false,
      canChangeProfession: false,
      isPro: false,
      isTrialing: false,
      isTrialExpired: true,
      streakDaysCompleted: 0,
      reason: 'CANCELED',
    };
  }

  const tier = Array.isArray(profile.tier) ? profile.tier[0] : profile.tier;
  const streaks = Array.isArray(profile.streaks) ? profile.streaks[0] : profile.streaks;

  const status = profile.subscription_status;
  const isPro = tier?.slug === 'pro' && status === 'active';
  const isTrialing = status === 'trialing';
  const totalCompletedDays = streaks?.longest_streak ?? 0;

  // Free Tier Rule: 3 completed days trial
  if (isTrialing) {
    if (totalCompletedDays >= 3) {
      return {
        canAccessDailyFeed: false,
        canChangeProfession: false,
        isPro: false,
        isTrialing: true,
        isTrialExpired: true,
        streakDaysCompleted: totalCompletedDays,
        reason: 'TRIAL_EXPIRED',
      };
    }

    return {
      canAccessDailyFeed: true,
      canChangeProfession: false,
      isPro: false,
      isTrialing: true,
      isTrialExpired: false,
      streakDaysCompleted: totalCompletedDays,
      reason: 'ACTIVE',
    };
  }

  if (status === 'active') {
    return {
      canAccessDailyFeed: true,
      canChangeProfession: (tier?.max_professions ?? 1) > 1,
      isPro: true,
      isTrialing: false,
      isTrialExpired: false,
      streakDaysCompleted: totalCompletedDays,
      reason: 'ACTIVE',
    };
  }

  return {
    canAccessDailyFeed: false,
    canChangeProfession: false,
    isPro: false,
    isTrialing: false,
    isTrialExpired: false,
    streakDaysCompleted: totalCompletedDays,
    reason: status === 'past_due' ? 'PAST_DUE' : 'CANCELED',
  };
}
```

